import json
P, R = [], []
def ins(a, b):
    P.extend([a, b])
def scan(a, drop):
    found = -1
    while P:
        b = P.pop(); k = P.pop()
        if k == a and found < 0:
            found = b
            if drop:
                continue
        R.extend([k, b])
    while R:
        b = R.pop(); k = R.pop()
        P.extend([k, b])
    return found
for a, b in [(2, 11), (4, 13), (2, 15)]:
    ins(a, b)
first = scan(2, False)
scan(2, True)
print(json.dumps({"get2": first, "get4": scan(4, False), "get2_after_removal": scan(2, False), "held": len(P) // 2}))
